local CastingLadleMaker = {}
local PRODUCTS = {
    iron_casting_ladle = { name = "Železna livarska zajemalka", ironCost = 5, woodCost = 1, leatherCost = 1, time = 6, cost = 205, prestige = 4, happiness = 2, description = "Železna zajemalka za prenos staljene kovine." },
    bronze_casting_ladle = { name = "Bronasta livarska zajemalka", bronzeCost = 5, ironCost = 1, woodCost = 1, leatherCost = 1, time = 8, cost = 495, prestige = 6, happiness = 3, description = "Bronasta zajemalka za varno litje." },
    silver_casting_ladle = { name = "Srebrna livarska zajemalka", silverCost = 5, bronzeCost = 1, ironCost = 1, woodCost = 1, leatherCost = 1, time = 12, cost = 1190, prestige = 11, happiness = 4, description = "Srebrna zajemalka za plemiške livarje." },
    gilded_casting_ladle = { name = "Pozlačena livarska zajemalka", goldCost = 1, silverCost = 5, bronzeCost = 1, woodCost = 1, leatherCost = 1, time = 16, cost = 2550, prestige = 20, happiness = 5, description = "Pozlačena zajemalka za dvorne livarje." },
    jewel_set_casting_ladle = { name = "Draguljasta livarska zajemalka", goldCost = 2, silverCost = 5, jewelCost = 1, bronzeCost = 1, woodCost = 1, leatherCost = 1, time = 20, cost = 5500, prestige = 36, happiness = 7, description = "Draguljasta zajemalka za kraljevske livarje." },
    royal_sovereign_casting_ladle = { name = "Kraljevski suverena livarska zajemalka", goldCost = 3, silverCost = 3, jewelCost = 2, pearlCost = 2, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 27, cost = 11700, prestige = 70, happiness = 13, description = "Suverena zajemalka z biseri za krono." },
}
local BUILDINGS = {
    castingladle_workshop = { name = "Zajemalna delavnica", cost = { gold = 380, wood = 175, stone = 155, iron = 11 }, upkeep = 7, qualityBonus = 5 },
    castingladle_house = { name = "Zajemalna hiša", cost = { gold = 1310, wood = 360, stone = 295, silver = 8, iron = 9 }, upkeep = 28, qualityBonus = 18 },
    master_castingladle_atelier = { name = "Mojstrski zajemalni atelje", cost = { gold = 3230, wood = 420, stone = 550, silver = 40, gold = 8 }, upkeep = 76, qualityBonus = 30 },
    sovereign_castingladle_palace = { name = "Suverena zajemalna palača", cost = { gold = 13800, wood = 655, stone = 870, gold = 89, jewel = 20 }, upkeep = 265, qualityBonus = 55, prestigeBonus = 50 },
}
CastingLadleMaker.ironStock = 18; CastingLadleMaker.bronzeStock = 14; CastingLadleMaker.woodStock = 10; CastingLadleMaker.leatherStock = 8; CastingLadleMaker.silverStock = 8; CastingLadleMaker.goldStock = 6; CastingLadleMaker.jewelStock = 4; CastingLadleMaker.pearlStock = 4
CastingLadleMaker.productStock = {}; CastingLadleMaker.buildings = {}; CastingLadleMaker.maker = nil; CastingLadleMaker.activeMaking = {}; CastingLadleMaker.totalProducts = 0; CastingLadleMaker.dayTimer = 0
function CastingLadleMaker.init() CastingLadleMaker.ironStock=18; CastingLadleMaker.bronzeStock=14; CastingLadleMaker.woodStock=10; CastingLadleMaker.leatherStock=8; CastingLadleMaker.silverStock=8; CastingLadleMaker.goldStock=6; CastingLadleMaker.jewelStock=4; CastingLadleMaker.pearlStock=4; CastingLadleMaker.productStock={}; CastingLadleMaker.buildings={}; CastingLadleMaker.maker=nil; CastingLadleMaker.activeMaking={}; CastingLadleMaker.totalProducts=0; CastingLadleMaker.dayTimer=0; print("[CastingLadleMaker] Royal Casting Ladle Maker System initialized (6 products, 4 buildings)") end
function CastingLadleMaker.hireMaker(n,s) s=s or math.random(55,90); local c=590+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; CastingLadleMaker.maker={name=n or ("Zajemalec "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Zajemalec najet: %s (spretnost: %d)",CastingLadleMaker.maker.name,s),"success") end; return true end
function CastingLadleMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function CastingLadleMaker.build(id) local ok,e=CastingLadleMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(CastingLadleMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function CastingLadleMaker.getQualityBonus() local b=0; for _,bd in ipairs(CastingLadleMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function CastingLadleMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and CastingLadleMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and CastingLadleMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and CastingLadleMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and CastingLadleMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and CastingLadleMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and CastingLadleMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and CastingLadleMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and CastingLadleMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #CastingLadleMaker.buildings==0 then return false,"Potrebna zajemalna delavnica" end; if not CastingLadleMaker.maker then return false,"Potreben zajemalec" end; return true end
function CastingLadleMaker.make(pt,qty) qty=qty or 1; local ok,e=CastingLadleMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then CastingLadleMaker.ironStock=CastingLadleMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then CastingLadleMaker.bronzeStock=CastingLadleMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then CastingLadleMaker.woodStock=CastingLadleMaker.woodStock-d.woodCost*qty end; if d.leatherCost then CastingLadleMaker.leatherStock=CastingLadleMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then CastingLadleMaker.silverStock=CastingLadleMaker.silverStock-d.silverCost*qty end; if d.goldCost then CastingLadleMaker.goldStock=CastingLadleMaker.goldStock-d.goldCost*qty end; if d.jewelCost then CastingLadleMaker.jewelStock=CastingLadleMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then CastingLadleMaker.pearlStock=CastingLadleMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if CastingLadleMaker.maker then t=math.max(1,t-math.floor(CastingLadleMaker.maker.skill/13)) end; table.insert(CastingLadleMaker.activeMaking,{id="castingladle_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function CastingLadleMaker.completeMaking(m) local q=1.0+(CastingLadleMaker.getQualityBonus()/100); if CastingLadleMaker.maker then q=q+(CastingLadleMaker.maker.skill/140) end; q=math.min(2.5,q); CastingLadleMaker.productStock[m.productType]=(CastingLadleMaker.productStock[m.productType] or 0)+m.quantity; CastingLadleMaker.totalProducts=CastingLadleMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if CastingLadleMaker.maker then CastingLadleMaker.maker.itemsMade=CastingLadleMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then CastingLadleMaker.maker.skill=math.min(100,CastingLadleMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Zajemalka izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"castingladle.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function CastingLadleMaker.update(dt) if not _G.state then return end; CastingLadleMaker.dayTimer=CastingLadleMaker.dayTimer+dt; if CastingLadleMaker.dayTimer>=30 then CastingLadleMaker.dayTimer=0; for i=#CastingLadleMaker.activeMaking,1,-1 do local m=CastingLadleMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then CastingLadleMaker.completeMaking(m); table.remove(CastingLadleMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(CastingLadleMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if CastingLadleMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function CastingLadleMaker.getStats() return {ironStock=CastingLadleMaker.ironStock,bronzeStock=CastingLadleMaker.bronzeStock,woodStock=CastingLadleMaker.woodStock,leatherStock=CastingLadleMaker.leatherStock,silverStock=CastingLadleMaker.silverStock,goldStock=CastingLadleMaker.goldStock,jewelStock=CastingLadleMaker.jewelStock,pearlStock=CastingLadleMaker.pearlStock,productStock=CastingLadleMaker.productStock,numBuildings=#CastingLadleMaker.buildings,hasMaker=CastingLadleMaker.maker~=nil,makerName=CastingLadleMaker.maker and CastingLadleMaker.maker.name or "—",makerSkill=CastingLadleMaker.maker and CastingLadleMaker.maker.skill or 0,activeMaking=#CastingLadleMaker.activeMaking,totalProducts=CastingLadleMaker.totalProducts} end
return CastingLadleMaker
